INSERT IGNORE INTO reporting_queries (slug,name,description,sql_query,is_system) VALUES ('dashboard-open-tickets','Dashboard - Open tickets','Dashboard panel: Open tickets.','SELECT id, subject FROM tickets WHERE company_id = {{current.company}} AND status NOT IN (''closed'',''resolved'')',1);
INSERT IGNORE INTO reporting_queries (slug,name,description,sql_query,is_system) VALUES ('dashboard-tickets-by-status','Dashboard - Tickets by status','Dashboard panel: Tickets by status.','SELECT status, COUNT(*) AS tickets FROM tickets WHERE company_id = {{current.company}} GROUP BY status ORDER BY tickets DESC',1);
INSERT IGNORE INTO reporting_queries (slug,name,description,sql_query,is_system) VALUES ('dashboard-tickets-created-30-days','Dashboard - Tickets created (30 days)','Dashboard panel: Tickets created (30 days).','SELECT DATE(created_at) AS day, COUNT(*) AS tickets FROM tickets WHERE company_id = {{current.company}} AND created_at >= CURRENT_DATE - INTERVAL 30 DAY GROUP BY DATE(created_at) ORDER BY day',1);
INSERT IGNORE INTO reporting_queries (slug,name,description,sql_query,is_system) VALUES ('dashboard-assets','Dashboard - Assets','Dashboard panel: Assets.','SELECT id, name FROM assets WHERE company_id = {{current.company}}',1);
INSERT IGNORE INTO reporting_queries (slug,name,description,sql_query,is_system) VALUES ('dashboard-assets-by-type','Dashboard - Assets by type','Dashboard panel: Assets by type.','SELECT COALESCE(asset_type, ''Other'') AS type, COUNT(*) AS assets FROM assets WHERE company_id = {{current.company}} GROUP BY asset_type ORDER BY assets DESC',1);
