INSERT IGNORE INTO reporting_queries (slug,name,description,sql_query,is_system) VALUES ('dashboard-calls-30-days','Dashboard - Calls (30 days)','Dashboard panel: Calls (30 days).','SELECT id, created_at FROM calls WHERE company_id = {{current.company}} AND created_at >= CURRENT_DATE - INTERVAL 30 DAY',1);
INSERT IGNORE INTO reporting_queries (slug,name,description,sql_query,is_system) VALUES ('dashboard-calls-by-day','Dashboard - Calls by day','Dashboard panel: Calls by day.','SELECT DATE(created_at) AS day, COUNT(*) AS calls FROM calls WHERE company_id = {{current.company}} AND created_at >= CURRENT_DATE - INTERVAL 30 DAY GROUP BY DATE(created_at) ORDER BY day',1);
INSERT IGNORE INTO reporting_queries (slug,name,description,sql_query,is_system) VALUES ('dashboard-quotes','Dashboard - Quotes','Dashboard panel: Quotes.','SELECT id, status FROM quotes WHERE company_id = {{current.company}}',1);
INSERT IGNORE INTO reporting_queries (slug,name,description,sql_query,is_system) VALUES ('dashboard-quotes-by-status','Dashboard - Quotes by status','Dashboard panel: Quotes by status.','SELECT status, COUNT(*) AS quotes FROM quotes WHERE company_id = {{current.company}} GROUP BY status',1);
INSERT IGNORE INTO reporting_queries (slug,name,description,sql_query,is_system) VALUES ('dashboard-ticket-replies-30-days','Dashboard - Ticket replies (30 days)','Dashboard panel: Ticket replies (30 days).','SELECT tr.id, tr.created_at FROM ticket_replies tr JOIN tickets t ON t.id=tr.ticket_id WHERE t.company_id = {{current.company}} AND tr.created_at >= CURRENT_DATE - INTERVAL 30 DAY',1);
INSERT IGNORE INTO reporting_queries (slug,name,description,sql_query,is_system) VALUES ('dashboard-ticket-time-by-day','Dashboard - Ticket time by day','Dashboard panel: Ticket time by day.','SELECT DATE(tr.created_at) AS day, SUM(COALESCE(tr.minutes_spent,0)) AS minutes FROM ticket_replies tr JOIN tickets t ON t.id=tr.ticket_id WHERE t.company_id = {{current.company}} AND tr.created_at >= CURRENT_DATE - INTERVAL 30 DAY GROUP BY DATE(tr.created_at) ORDER BY day',1);
INSERT IGNORE INTO reporting_queries (slug,name,description,sql_query,is_system) VALUES ('dashboard-global-companies','Dashboard - Global companies','Dashboard panel: Global companies.','SELECT id, name FROM companies',1);
INSERT IGNORE INTO reporting_queries (slug,name,description,sql_query,is_system) VALUES ('dashboard-global-users','Dashboard - Global users','Dashboard panel: Global users.','SELECT id, email FROM users',1);
INSERT IGNORE INTO reporting_queries (slug,name,description,sql_query,is_system) VALUES ('dashboard-global-tickets-by-company','Dashboard - Global tickets by company','Dashboard panel: Global tickets by company.','SELECT c.name AS company, COUNT(t.id) AS tickets FROM companies c LEFT JOIN tickets t ON t.company_id=c.id GROUP BY c.id,c.name ORDER BY tickets DESC',1);
INSERT IGNORE INTO reporting_queries (slug,name,description,sql_query,is_system) VALUES ('dashboard-global-assets-by-company','Dashboard - Global assets by company','Dashboard panel: Global assets by company.','SELECT c.name AS company, COUNT(a.id) AS assets FROM companies c LEFT JOIN assets a ON a.company_id=c.id GROUP BY c.id,c.name ORDER BY assets DESC',1);
INSERT IGNORE INTO reporting_queries (slug,name,description,sql_query,is_system) VALUES ('dashboard-global-staff-by-company','Dashboard - Global staff by company','Dashboard panel: Global staff by company.','SELECT c.name AS company, COUNT(s.id) AS staff FROM companies c LEFT JOIN staff s ON s.company_id=c.id GROUP BY c.id,c.name ORDER BY staff DESC',1);
INSERT IGNORE INTO reporting_queries (slug,name,description,sql_query,is_system) VALUES ('dashboard-notifications','Dashboard - Notifications','Dashboard panel: Notifications.','SELECT id, event_type FROM notifications WHERE user_id IS NOT NULL',1);
